def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the full row or column divider.
    div_row = next((r for r in range(h) if all(v == 2 for v in grid[r])), None)
    div_col = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)

    background = max(
        (v for v in range(10) if v != 2),
        key=lambda v: sum(cell == v for row in grid for cell in row)
    )
    obj = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] not in (2, background)]
    if not obj:
        return out

    if div_row is not None:
        if min(r for r, c in obj) > div_row:  # object below divider
            shift = div_row + 1 - min(r for r, c in obj)
            stripe = max(r for r, c in obj) + shift + 1
        else:  # object above divider
            shift = div_row - 1 - max(r for r, c in obj)
            stripe = min(r for r, c in obj) + shift - 1
        for r, c in obj:
            out[r][c] = background
        for r, c in obj:
            nr = r + shift
            if 0 <= nr < h:
                out[nr][c] = grid[r][c]
        if 0 <= stripe < h:
            out[stripe] = [8] * w

    elif div_col is not None:
        if min(c for r, c in obj) > div_col:  # object right of divider
            shift = div_col + 1 - min(c for r, c in obj)
            stripe = max(c for r, c in obj) + shift + 1
        else:  # object left of divider
            shift = div_col - 1 - max(c for r, c in obj)
            stripe = min(c for r, c in obj) + shift - 1
        for r, c in obj:
            out[r][c] = background
        for r, c in obj:
            nc = c + shift
            if 0 <= nc < w:
                out[r][nc] = grid[r][c]
        if 0 <= stripe < w:
            for r in range(h):
                out[r][stripe] = 8

    return out
